1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
tools/power turbostat: option '-n' is ambiguous

In some cases specifying the '-n' command line argument will cause
turbostat to fail.  For instance 'turbostat -n 1' works fine; however,
'turbostat -n 1 -d' will fail.  This is the result of the first call
to getopt_long_only() where "MP" is specified as the optstring.  This can
be easily fixed by changing the optstring from "MP" to "MPn:" to remove
ambiguity between the arguments.

tools/power turbostat: option '-n' is ambiguous; possibilities: '-num_iterations' '-no-msr' '-no-perf'

Fixes: a0e86c90b83c ("tools/power turbostat: Add --no-perf option")

Signed-off-by: David Arcari <darcari@redhat.com>
Signed-off-by: Len Brown <len.brown@intel.com>

Here is the root cause:
The bug arises from the ambiguity in the command-line options due to the `optstring` used in the `getopt_long_only()` function. The original `optstring` of `"MP"` did not account for the `-n` option, leading to conflicts with other options like `--no-perf`, causing the program to fail when both were specified together. By not properly defining the `-n` option in the `optstring`, the parser could not distinguish it from other similar options, resulting in incorrect behavior.

Here is the patch:

 void cmdline(int argc, char **argv)
 {
 	int opt;
 	int option_index = 0;
 	static struct option long_options[] = {
 		{ "add", required_argument, 0, 'a' },
 		{ "cpu", required_argument, 0, 'c' },
 		{ "Dump", no_argument, 0, 'D' },
 		{ "debug", no_argument, 0, 'd' },	/* internal, not documented */
 		{ "enable", required_argument, 0, 'e' },
 		{ "interval", required_argument, 0, 'i' },
 		{ "IPC", no_argument, 0, 'I' },
 		{ "num_iterations", required_argument, 0, 'n' },
 		{ "header_iterations", required_argument, 0, 'N' },
 		{ "help", no_argument, 0, 'h' },
 		{ "hide", required_argument, 0, 'H' },	// meh, -h taken by --help
 		{ "Joules", no_argument, 0, 'J' },
 		{ "list", no_argument, 0, 'l' },
 		{ "out", required_argument, 0, 'o' },
 		{ "quiet", no_argument, 0, 'q' },
 		{ "no-msr", no_argument, 0, 'M' },
 		{ "no-perf", no_argument, 0, 'P' },
 		{ "show", required_argument, 0, 's' },
 		{ "Summary", no_argument, 0, 'S' },
 		{ "TCC", required_argument, 0, 'T' },
 		{ "version", no_argument, 0, 'v' },
 		{ 0, 0, 0, 0 }
 	};

 	progname = argv[0];

 	/*
 	 * Parse some options early, because they may make other options invalid,
 	 * like adding the MSR counter with --add and at the same time using --no-msr.
 	 */
-	while ((opt = getopt_long_only(argc, argv, "MP", long_options, &option_index)) != -1) {
+	while ((opt = getopt_long_only(argc, argv, "MPn:", long_options, &option_index)) != -1) {
 		switch (opt) {
 		case 'M':
 			no_msr = 1;
 			break;
 		case 'P':
 			no_perf = 1;
 			break;
 		default:
 			break;
 		}
 	}
 	optind = 0;

 	while ((opt = getopt_long_only(argc, argv, "+C:c:Dde:hi:Jn:o:qMST:v", long_options, &option_index)) != -1) {
 		switch (opt) {
 		case 'a':
 			parse_add_command(optarg);
 			break;
 		case 'c':
 			parse_cpu_command(optarg);
 			break;
 		case 'D':
 			dump_only++;
 			break;
 		case 'e':
 			/* --enable specified counter */
 			bic_enabled = bic_enabled | bic_lookup(optarg, SHOW_LIST);
 			break;
 		case 'd':
 			debug++;
 			ENABLE_BIC(BIC_DISABLED_BY_DEFAULT);
 			break;
 		case 'H':
 			/*
 			 * --hide: do not show those specified
 			 *  multiple invocations simply clear more bits in enabled mask
 			 */
 			bic_enabled &= ~bic_lookup(optarg, HIDE_LIST);
 			break;
 		case 'h':
 		default:
 			help();
 			exit(1);
 		case 'i':
 			{
 				double interval = strtod(optarg, NULL);

 				if (interval < 0.001) {
 					fprintf(outf, "interval %f seconds is too small\n", interval);
 					exit(2);
 				}

 				interval_tv.tv_sec = interval_ts.tv_sec = interval;
 				interval_tv.tv_usec = (interval - interval_tv.tv_sec) * 1000000;
 				interval_ts.tv_nsec = (interval - interval_ts.tv_sec) * 1000000000;
 			}
 			break;
 		case 'J':
 			rapl_joules++;
 			break;
 		case 'l':
 			ENABLE_BIC(BIC_DISABLED_BY_DEFAULT);
 			list_header_only++;
 			quiet++;
 			break;
 		case 'o':
 			outf = fopen_or_die(optarg, "w");
 			break;
 		case 'q':
 			quiet = 1;
 			break;
 		case 'M':
 		case 'P':
 			/* Parsed earlier */
 			break;
 		case 'n':
 			num_iterations = strtod(optarg, NULL);

 			if (num_iterations <= 0) {
 				fprintf(outf, "iterations %d should be positive number\n", num_iterations);
 				exit(2);
 			}
 			break;
 		case 'N':
 			header_iterations = strtod(optarg, NULL);

 			if (header_iterations <= 0) {
 				fprintf(outf, "iterations %d should be positive number\n", header_iterations);
 				exit(2);
 			}
 			break;
 		case 's':
 			/*
 			 * --show: show only those specified
 			 *  The 1st invocation will clear and replace the enabled mask
 			 *  subsequent invocations can add to it.
 			 */
 			if (shown == 0)
 				bic_enabled = bic_lookup(optarg, SHOW_LIST);
 			else
 				bic_enabled |= bic_lookup(optarg, SHOW_LIST);
 			shown = 1;
 			break;
 		case 'S':
 			summary_only++;
 			break;
 		case 'T':
 			tj_max_override = atoi(optarg);
 			break;
 		case 'v':
 			print_version();
 			exit(0);
 			break;
 		}
 	}
 }



